static size_t __parse_mem_copy(struct _light_pcapng **iter, const uint32_t *memory, const size_t size)
{
   struct _light_pcapng *current = NULL;
   size_t bytes_read = 0;
   size_t remaining = size;
   size_t block_count = 0;

   *iter = NULL;

